"use client";

import { useState, useEffect, useCallback, useRef } from "react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { 
  Bot, Mic, Brain, Volume2, Phone, Loader2, Zap, 
  Sparkles, Play, CheckCircle2, Settings2, MessageSquare
} from "lucide-react";
import { useRouter } from "next/navigation";
import { useToast } from "@/hooks/use-toast";
import { Switch } from "@/components/ui/switch";
import api from "@/lib/api";

// Default/Fallback Models (Free Tier)
const DEFAULT_STT_MODELS = [
  { value: "deepgram/nova-3", label: "Deepgram Nova 3", description: "Best accuracy" },
  { value: "deepgram/nova-2", label: "Deepgram Nova 2", description: "Great accuracy" },
];

const DEFAULT_LLM_MODELS = [
  { value: "groq/llama-3.3-70b-versatile", label: "Llama 3.3 70B", description: "Ultra fast", provider: "Groq" },
  { value: "openai/gpt-4o-mini", label: "GPT-4o Mini", description: "Cost-effective", provider: "OpenAI" },
];

const DEFAULT_TTS_VOICES = [
  { value: "79a125e8-cd45-4c13-8a67-188112f4dd22", label: "Sarah", description: "Female, Professional", provider: "Cartesia" },
  { value: "9626c31c-bec5-4cca-baa8-f8ba9e84c8bc", label: "Parker", description: "Male, Friendly", provider: "Cartesia" },
];

interface AgentConfig {
  name: string;
  system_prompt: string;
  first_message: string;
  llm_model: string;
  stt_model: string;
  voice_id: string;
  voice_provider: string;
  tools_config: {
    check_availability: boolean;
    book_appointment: boolean;
    cancel_appointment: boolean;
    get_business_info: boolean;
  };
}

interface ModelOption {
  value: string;
  label: string;
  description?: string;
  provider?: string;
  gender?: string;
}

export default function AISettingsPage() {
  const router = useRouter();
  const { toast } = useToast();
  
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [lastSaved, setLastSaved] = useState<Date | null>(null);
  const [hasChanges, setHasChanges] = useState(false);
  const [previewingVoice, setPreviewingVoice] = useState(false);
  const [hasElevenLabsKey, setHasElevenLabsKey] = useState(false);
  const [startingCall, setStartingCall] = useState(false);
  
  // Dynamic Lists
  const [sttModels] = useState<ModelOption[]>(DEFAULT_STT_MODELS);
  const [llmModels, setLlmModels] = useState<ModelOption[]>(DEFAULT_LLM_MODELS);
  const [ttsVoices, setTtsVoices] = useState<ModelOption[]>(DEFAULT_TTS_VOICES);

  const [config, setConfig] = useState<AgentConfig>({
    name: "AI Receptionist",
    system_prompt: "You are a friendly AI receptionist. Help customers book appointments and answer questions about the business.",
    first_message: "Hello! I'm your AI receptionist. How can I help you today?",
    llm_model: "groq/llama-3.3-70b-versatile",
    stt_model: "deepgram/nova-3",
    voice_id: "79a125e8-cd45-4c13-8a67-188112f4dd22",
    voice_provider: "cartesia",
    tools_config: {
      check_availability: true,
      book_appointment: true,
      cancel_appointment: true,
      get_business_info: true,
    }
  });

  // Auto-save debounce ref
  const saveTimeoutRef = useRef<NodeJS.Timeout | null>(null);

  useEffect(() => {
    loadData();
  }, []);

  // Auto-save on config change
  useEffect(() => {
    if (!loading && hasChanges) {
      if (saveTimeoutRef.current) {
        clearTimeout(saveTimeoutRef.current);
      }
      saveTimeoutRef.current = setTimeout(() => {
        autoSave();
      }, 1500); // 1.5 second debounce
    }
    return () => {
      if (saveTimeoutRef.current) {
        clearTimeout(saveTimeoutRef.current);
      }
    };
  }, [config, hasChanges, loading]);

  const loadData = async () => {
    try {
      setLoading(true);
      
      // 1. Fetch API Keys to know what providers are available
      const keysRes = await api.get("/keys");
      const apiKeys = keysRes.data || [];
      const providers = apiKeys.map((k: any) => k.provider).filter(Boolean);
      
      setHasElevenLabsKey(providers.includes('elevenlabs'));

      // 2. Fetch dynamic models/voices
      const promises = [];
      
      if (providers.includes('groq')) {
        promises.push(
          api.get("/keys/groq/models").then(res => ({ type: 'llm', provider: 'groq', data: res.data })).catch(() => null)
        );
      }
      
      if (providers.includes('openai')) {
        promises.push(
          api.get("/keys/openai/models").then(res => ({ type: 'llm', provider: 'openai', data: res.data })).catch(() => null)
        );
      }
      
      if (providers.includes('elevenlabs')) {
        promises.push(
          api.get("/keys/elevenlabs/voices").then(res => ({ type: 'voice', provider: 'elevenlabs', data: res.data })).catch(() => null)
        );
      }
      
      if (providers.includes('cartesia')) {
        promises.push(
          api.get("/keys/cartesia/voices").then(res => ({ type: 'voice', provider: 'cartesia', data: res.data })).catch(() => null)
        );
      }

      const results = await Promise.all(promises);
      
      // Merge results
      const newLlmModels = [...DEFAULT_LLM_MODELS];
      const newTtsVoices = [...DEFAULT_TTS_VOICES];

      results.forEach(r => {
        if (!r) return;

        if (r.type === 'llm') {
          const providerName = r.provider === 'groq' ? 'Groq' : 'OpenAI';
          (r.data || []).forEach((m: any) => {
            if (!newLlmModels.find(x => x.value === m.id)) {
              newLlmModels.push({
                value: m.id,
                label: m.id.split('/').pop() || m.id,
                description: "Your API",
                provider: providerName
              });
            }
          });
        }
        
        if (r.type === 'voice') {
          const voices = Array.isArray(r.data) ? r.data : r.data?.voices || [];
          voices.forEach((v: any) => {
            const voiceId = v.voice_id || v.id;
            if (!newTtsVoices.find(x => x.value === voiceId)) {
              newTtsVoices.push({
                value: voiceId,
                label: v.name,
                description: v.labels?.accent || v.description || r.provider,
                gender: v.labels?.gender,
                provider: r.provider === 'elevenlabs' ? 'ElevenLabs' : 'Cartesia'
              });
            }
          });
        }
      });
      
      setLlmModels(newLlmModels);
      setTtsVoices(newTtsVoices);

      // 3. Fetch current AI config
      try {
        const configRes = await api.get("/ai-config");
        if (configRes.data) {
          setConfig({
            name: configRes.data.name || "AI Receptionist",
            system_prompt: configRes.data.system_prompt || "",
            first_message: configRes.data.first_message || "Hello!",
            llm_model: configRes.data.llm_model || "groq/llama-3.3-70b-versatile",
            stt_model: configRes.data.stt_model || "deepgram/nova-3",
            voice_id: configRes.data.voice_id || DEFAULT_TTS_VOICES[0].value,
            voice_provider: configRes.data.voice_provider || "cartesia",
            tools_config: configRes.data.tools_config || config.tools_config,
          });
        }
      } catch (e) {
        console.log("Using defaults for AI config");
      }
    } catch (error) {
      console.error("Failed to load:", error);
      toast({ title: "Warning", description: "Could not load all options. Using defaults." });
    } finally {
      setLoading(false);
    }
  };

  const updateConfig = useCallback((updates: Partial<AgentConfig>) => {
    setConfig(prev => ({ ...prev, ...updates }));
    setHasChanges(true);
  }, []);

  const autoSave = async () => {
    setSaving(true);
    try {
      await api.put("/ai-config", config);
      setLastSaved(new Date());
      setHasChanges(false);
      toast({
        title: "✨ AI Updated",
        description: "Your agent is now live with the new configuration!",
      });
    } catch (error) {
      console.error("Auto-save failed:", error);
      toast({
        title: "Save failed",
        description: "Could not save. Please try again.",
        variant: "destructive",
      });
    } finally {
      setSaving(false);
    }
  };

  const previewVoice = async () => {
    if (!hasElevenLabsKey) {
      toast({ title: "Add ElevenLabs key", description: "Voice preview requires an ElevenLabs API key." });
      return;
    }
    
    setPreviewingVoice(true);
    try {
      const response = await api.post(`/keys/elevenlabs/preview?voice_id=${config.voice_id}&text=${encodeURIComponent(config.first_message || "Hello! How can I help you today?")}`, {}, { responseType: 'blob' });
      const audioUrl = URL.createObjectURL(response.data);
      const audio = new Audio(audioUrl);
      audio.play();
    } catch (error) {
      toast({ title: "Preview failed", description: "Could not generate voice preview.", variant: "destructive" });
    } finally {
      setPreviewingVoice(false);
    }
  };

  const startTestCall = async () => {
    setStartingCall(true);
    try {
      // First save current config
      await api.put("/ai-config", config);
      // Navigate to test call page
      router.push("/dashboard/voice-agent/test");
    } catch (error) {
      toast({ title: "Error", description: "Could not start test call.", variant: "destructive" });
      setStartingCall(false);
    }
  };

  if (loading) {
    return (
      <div className="flex flex-col items-center justify-center h-[60vh] gap-4">
        <div className="relative">
          <Bot className="w-16 h-16 text-primary animate-pulse" />
          <Sparkles className="w-6 h-6 text-yellow-500 absolute -top-1 -right-1 animate-bounce" />
        </div>
        <p className="text-muted-foreground">Loading your AI configuration...</p>
      </div>
    );
  }

  return (
    <div className="container mx-auto p-6 max-w-5xl space-y-8">
      {/* Hero Header */}
      <div className="text-center space-y-4 pb-6 border-b">
        <div className="flex items-center justify-center gap-3">
          <div className="p-3 rounded-2xl bg-gradient-to-br from-primary/20 to-purple-500/20">
            <Bot className="w-10 h-10 text-primary" />
          </div>
          <div className="text-left">
            <h1 className="text-3xl font-bold bg-gradient-to-r from-primary to-purple-600 bg-clip-text text-transparent">
              Your AI Receptionist
            </h1>
            <p className="text-muted-foreground">
              Configure how your AI sounds, thinks, and behaves
            </p>
          </div>
        </div>
        
        {/* Status Bar */}
        <div className="flex items-center justify-center gap-4 text-sm">
          {saving ? (
            <Badge variant="outline" className="gap-1">
              <Loader2 className="w-3 h-3 animate-spin" />
              Saving...
            </Badge>
          ) : lastSaved ? (
            <Badge variant="outline" className="gap-1 bg-green-50 text-green-700 border-green-200">
              <CheckCircle2 className="w-3 h-3" />
              Auto-saved {lastSaved.toLocaleTimeString()}
            </Badge>
          ) : null}
          
          <Badge variant="secondary" className="gap-1">
            <Zap className="w-3 h-3" />
            Changes update LiveKit instantly
          </Badge>
        </div>
      </div>

      {/* Quick Actions */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        <Card className="border-2 border-dashed border-primary/30 bg-gradient-to-br from-primary/5 to-purple-500/5 hover:border-primary/50 transition-colors">
          <CardContent className="p-6">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-4">
                <div className="p-3 rounded-xl bg-primary/10">
                  <Phone className="w-6 h-6 text-primary" />
                </div>
                <div>
                  <h3 className="font-semibold text-lg">Test Your AI</h3>
                  <p className="text-sm text-muted-foreground">
                    Start a live call to hear your configuration
                  </p>
                </div>
              </div>
              <Button 
                size="lg" 
                onClick={startTestCall}
                disabled={startingCall}
                className="bg-gradient-to-r from-primary to-purple-600 hover:from-primary/90 hover:to-purple-600/90"
              >
                {startingCall ? <Loader2 className="w-4 h-4 mr-2 animate-spin" /> : <Phone className="w-4 h-4 mr-2" />}
                Start Test Call
              </Button>
            </div>
          </CardContent>
        </Card>

        <Card className="border-2 border-dashed hover:border-primary/30 transition-colors">
          <CardContent className="p-6">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-4">
                <div className="p-3 rounded-xl bg-secondary">
                  <Volume2 className="w-6 h-6" />
                </div>
                <div>
                  <h3 className="font-semibold text-lg">Preview Voice</h3>
                  <p className="text-sm text-muted-foreground">
                    Hear how your AI will sound
                  </p>
                </div>
              </div>
              <Button 
                variant="outline" 
                size="lg"
                onClick={previewVoice}
                disabled={previewingVoice}
              >
                {previewingVoice ? <Loader2 className="w-4 h-4 mr-2 animate-spin" /> : <Play className="w-4 h-4 mr-2" />}
                Play Sample
              </Button>
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Main Configuration */}
      <Tabs defaultValue="voice" className="space-y-6">
        <TabsList className="grid w-full grid-cols-4 h-12">
          <TabsTrigger value="voice" className="gap-2">
            <Volume2 className="w-4 h-4" />
            Voice
          </TabsTrigger>
          <TabsTrigger value="brain" className="gap-2">
            <Brain className="w-4 h-4" />
            Brain
          </TabsTrigger>
          <TabsTrigger value="behavior" className="gap-2">
            <MessageSquare className="w-4 h-4" />
            Behavior
          </TabsTrigger>
          <TabsTrigger value="tools" className="gap-2">
            <Settings2 className="w-4 h-4" />
            Tools
          </TabsTrigger>
        </TabsList>

        {/* Voice Tab */}
        <TabsContent value="voice" className="space-y-6">
          <Card>
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <Volume2 className="w-5 h-5 text-primary" />
                Voice Selection
              </CardTitle>
              <CardDescription>
                Choose the voice your AI will use when speaking to customers
              </CardDescription>
            </CardHeader>
            <CardContent className="space-y-6">
              <div className="space-y-3">
                <Label className="text-base font-medium">AI Voice</Label>
                <Select 
                  value={config.voice_id} 
                  onValueChange={(value) => {
                    const voice = ttsVoices.find(v => v.value === value);
                    updateConfig({ 
                      voice_id: value,
                      voice_provider: voice?.provider?.toLowerCase() || "cartesia"
                    });
                  }}
                >
                  <SelectTrigger className="h-12">
                    <SelectValue placeholder="Select a voice" />
                  </SelectTrigger>
                  <SelectContent>
                    {ttsVoices.map((voice) => (
                      <SelectItem key={voice.value} value={voice.value}>
                        <div className="flex items-center gap-3">
                          <span className="font-medium">{voice.label}</span>
                          <Badge variant="outline" className="text-xs">
                            {voice.provider}
                          </Badge>
                          {voice.description && (
                            <span className="text-muted-foreground text-xs">
                              {voice.description}
                            </span>
                          )}
                        </div>
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
                {!hasElevenLabsKey && (
                  <p className="text-sm text-muted-foreground flex items-center gap-1">
                    <Sparkles className="w-3 h-3" />
                    Add an ElevenLabs API key to unlock 100+ premium voices
                  </p>
                )}
              </div>

              <div className="space-y-3">
                <Label className="text-base font-medium">First Message</Label>
                <Textarea
                  value={config.first_message}
                  onChange={(e) => updateConfig({ first_message: e.target.value })}
                  placeholder="Hello! How can I help you today?"
                  rows={2}
                  className="resize-none"
                />
                <p className="text-sm text-muted-foreground">
                  This is the first thing your AI will say when answering a call
                </p>
              </div>
            </CardContent>
          </Card>

          <Card>
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <Mic className="w-5 h-5 text-primary" />
                Speech Recognition
              </CardTitle>
              <CardDescription>
                How your AI hears and understands customers
              </CardDescription>
            </CardHeader>
            <CardContent>
              <Select 
                value={config.stt_model} 
                onValueChange={(value) => updateConfig({ stt_model: value })}
              >
                <SelectTrigger className="h-12">
                  <SelectValue placeholder="Select STT model" />
                </SelectTrigger>
                <SelectContent>
                  {sttModels.map((model) => (
                    <SelectItem key={model.value} value={model.value}>
                      <div className="flex items-center gap-2">
                        <span className="font-medium">{model.label}</span>
                        <span className="text-muted-foreground text-xs">— {model.description}</span>
                      </div>
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </CardContent>
          </Card>
        </TabsContent>

        {/* Brain Tab */}
        <TabsContent value="brain" className="space-y-6">
          <Card>
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <Brain className="w-5 h-5 text-primary" />
                AI Brain (Language Model)
              </CardTitle>
              <CardDescription>
                The intelligence behind your AI's responses
              </CardDescription>
            </CardHeader>
            <CardContent>
              <Select 
                value={config.llm_model} 
                onValueChange={(value) => updateConfig({ llm_model: value })}
              >
                <SelectTrigger className="h-12">
                  <SelectValue placeholder="Select LLM" />
                </SelectTrigger>
                <SelectContent>
                  {llmModels.map((model) => (
                    <SelectItem key={model.value} value={model.value}>
                      <div className="flex items-center gap-3">
                        <span className="font-medium">{model.label}</span>
                        {model.provider && (
                          <Badge variant="outline" className="text-xs">
                            {model.provider}
                          </Badge>
                        )}
                        {model.description && (
                          <span className="text-muted-foreground text-xs">
                            {model.description}
                          </span>
                        )}
                      </div>
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </CardContent>
          </Card>
        </TabsContent>

        {/* Behavior Tab */}
        <TabsContent value="behavior" className="space-y-6">
          <Card>
            <CardHeader>
              <CardTitle>Agent Identity</CardTitle>
              <CardDescription>
                Define your AI's name and personality
              </CardDescription>
            </CardHeader>
            <CardContent className="space-y-6">
              <div className="space-y-3">
                <Label className="text-base font-medium">Agent Name</Label>
                <Input
                  value={config.name}
                  onChange={(e) => updateConfig({ name: e.target.value })}
                  placeholder="AI Receptionist"
                  className="h-12"
                />
              </div>

              <div className="space-y-3">
                <Label className="text-base font-medium">System Prompt</Label>
                <Textarea
                  value={config.system_prompt}
                  onChange={(e) => updateConfig({ system_prompt: e.target.value })}
                  placeholder="You are a friendly AI receptionist..."
                  rows={8}
                  className="font-mono text-sm"
                />
                <p className="text-sm text-muted-foreground">
                  Instructions that define how your AI behaves and responds
                </p>
              </div>
            </CardContent>
          </Card>
        </TabsContent>

        {/* Tools Tab */}
        <TabsContent value="tools" className="space-y-6">
          <Card>
            <CardHeader>
              <CardTitle>Agent Capabilities</CardTitle>
              <CardDescription>
                Control what your AI can do during calls
              </CardDescription>
            </CardHeader>
            <CardContent className="space-y-6">
              {[
                { key: "check_availability", label: "Check Availability", desc: "Look up available appointment slots" },
                { key: "book_appointment", label: "Book Appointments", desc: "Create new bookings for customers" },
                { key: "cancel_appointment", label: "Cancel Appointments", desc: "Cancel existing bookings" },
                { key: "get_business_info", label: "Business Info", desc: "Answer questions about hours, services, etc." },
              ].map((tool) => (
                <div key={tool.key} className="flex items-center justify-between py-3 border-b last:border-0">
                  <div className="space-y-0.5">
                    <Label className="text-base font-medium">{tool.label}</Label>
                    <p className="text-sm text-muted-foreground">{tool.desc}</p>
                  </div>
                  <Switch
                    checked={config.tools_config[tool.key as keyof typeof config.tools_config]}
                    onCheckedChange={(checked) => 
                      updateConfig({ 
                        tools_config: { 
                          ...config.tools_config, 
                          [tool.key]: checked 
                        } 
                      })
                    }
                  />
                </div>
              ))}
            </CardContent>
          </Card>
        </TabsContent>
      </Tabs>
    </div>
  );
}
